import {mergeOzExperiences} from '/core/oz-experiences.mjs';
import {migrateLifecycle,groupOperations,createGroup,attachOperation,createBlankOperation,lifecycleSummary} from '/core/lifecycle.mjs';
import { duplicateRoom } from '/core/rooms.mjs';
import {fullForecast,compare,num,ceil,forecastTraffic,turnaround} from '/core/forecast.mjs';
import {partnerSettlement} from '/core/partners.mjs';
import {computeRevenueRoutes,SOURCE_LABELS} from '/core/revenue-routes.mjs';
import {seedQuote,totals as quoteTotals,quoteCsv,quoteXlsx} from '/core/quotes.mjs';
import {defaultQuoteLayout, normalizeQuoteLayout, moveQuoteBlock,upgradeQuoteLayout} from '/core/quote-layout.mjs';
import {detailDisclosure,rowSale,materialChangeSet,canMutateQuote,synchronizeQuoteRows} from '/core/quote-details.mjs';
import {setupExperienceFit,installationRequirement} from '/core/setup-compatibility.mjs';
import {defaultDocumentTemplates,normalizeDocumentTemplates,snapshotTemplate,applyTemplate,tableColumns,displayedTableColumns,updateTableColumns,moveTableColumn} from '/core/document-templates.mjs';
// Cette copie du moteur est servie en lecture seule (voir serveur, route /core/).
let state=null,tab='home',saveTimer=null,results=null;let selectedExperienceGroup=null;let xpLibrarySearch='';
let missionManagerOpen=false;
let workspaceTab='overview',selectedNode=null,workspaceFull=false,showCompletion=false,quickNew=false,showAllXps=false,projectSearch='';
let projectContext = new Map(),renameProject=false;let journeyStep=0;let selectedGroupId=null;
let trafficPeriod={start:'',end:''};let renderedTab=null;let navGroupsOpen=(()=>{try{return JSON.parse(localStorage.getItem('forecast-nav-groups'))||{settings:true,financial:true}}catch{return {settings:true,financial:true}}})();
const menu=[['dashboard','◫','Vue d’ensemble'],['projects','▣','Projets & scénarios'],['experiences','◈','Expériences'],['operations','▦','Lieux & setups'],['traffic','◷','Flux & fréquentation'],['staff','♧','Personnel & OPEX'],['catalog','◉','Catalogue matériel'],['capex','▤','CAPEX & devis'],['deployment','♧','Prestations & logistique'],['finance','€','Finance & rentabilité'],['history','↺','Historique & réalisé'],['exports','⇩','Rapports & sauvegardes']];
const $=sel=>document.querySelector(sel);
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const fmt=(v,d=0)=>v==null?'—':new Intl.NumberFormat('fr-FR',{maximumFractionDigits:d,minimumFractionDigits:d}).format(v);
const eur=v=>v==null?'À vérifier':new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(v);
const uid=()=>crypto.randomUUID();
const active=()=>state.projects.find(x=>x.id===state.activeId)||state.projects[0];
const weekNames=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];
const emptyWeek=()=>weekNames.map((_,i)=>({open:i<6,start:'10:00',end:'18:00'}));
function note(message){const e=$('#toast');e.textContent=message;e.classList.remove('hidden');setTimeout(()=>e.classList.add('hidden'),3200)}
function recompute(){results=fullForecast(active(),state.catalog)}
function scheduleSave(){const e=$('#saveStatus');e.textContent='Modifications…';clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,700)}
async function saveNow(){try{const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)});if(!r.ok)throw new Error((await r.json()).error);$('#saveStatus').textContent='Enregistré ✓'}catch(e){$('#saveStatus').textContent='⚠ Non enregistré';note(e.message)}}
function update(){migrateLifecycle(state,uid);recompute();render();scheduleSave()}
function projectNameEditor(p){return `<div class="project-name-editor"><input id="projectNameInline" aria-label="Nom du projet" maxlength="180" value="${esc(p.name)}"><button class="btn sm secondary" data-action="finishRename">✓ Enregistrer</button><button class="btn sm ghost" data-action="cancelRename">Annuler</button></div>`}
function projectNameDisplay(p){return `<span class="project-name-inline" role="button" tabindex="0" data-action="startRename" title="Cliquer pour renommer ce projet">${esc(p.name)}</span><button class="rename-trigger" type="button" data-action="startRename" aria-label="Renommer le projet ${esc(p.name)}" title="Renommer ce projet">✎</button>`}
function contextHeader(p){const common=tab==='experiences'||tab==='catalog';const tag=tab==='catalog'?'Catalogue partagé — Matériel':tab==='experiences'?'Expériences de ce projet · Bibliothèque commune accessible':null;return `<div class="context-header"><div class="context-heading"><small>${esc(tag||'PROJET ACTIF')} · ${esc(dataMeta(p).status||'En étude')}</small><div class="context-name">${renameProject?projectNameEditor(p):projectNameDisplay(p)}</div></div><div class="context-actions"><span class="badge good" id="contextProjectStatus">${esc(levelLabel(p))}</span>${action('◈ Dossier & phases','lifecycleGroup:'+(p.groupId||''),'sm ghost')}${action('↗ Espace projet','uxWorkspace','sm secondary')}</div></div>`}
function field(label,bind,value,type='text',extra=''){return `<div class="field"><label>${esc(label)}${label.includes('Intervalle entre lancements')?help('Temps entre la fin de la partie et le début de la suivante.'):''}</label><input type="${type}" data-bind="${esc(bind)}" value="${esc(value??'')}" ${extra}></div>`}
function choice(label,bind,value,opts){return `<div class="field"><label>${esc(label)}</label><select data-bind="${esc(bind)}">${opts.map(o=>{let v=Array.isArray(o)?o[0]:o,t=Array.isArray(o)?o[1]:o;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`}
function check(label,bind,value){return `<label class="field" style="flex-direction:row;align-items:center"><input type="checkbox" data-bind="${esc(bind)}" ${value?'checked':''}> ${esc(label)}</label>`}
function hourInput(bind,value){return `<input type="text" class="time-entry" inputmode="numeric" maxlength="5" placeholder="HH:MM" pattern="(?:[01][0-9]|2[0-3]):[0-5][0-9]" title="Saisir une heure sur 24 h, par exemple 09:30" data-bind="${esc(bind)}" value="${esc(value||'')}">`}
function help(content){return `<button type="button" class="help-icon" aria-label="Aide : ${esc(content)}" title="${esc(content)}">?</button>`}
function multiPicker(label,kind,selected=[],index,options=[]){
 const all=[...new Set([...options,...selected])].filter(Boolean);
 return `<div class="field picker"><label>${esc(label)} ${help('Sélectionnez plusieurs références ou ajoutez-en avec le bouton +.')}</label><div class="picker-list">${all.map(v=>`<label><input type="checkbox" data-picker="${kind}" data-xp="${index}" value="${esc(v)}" ${selected.includes(v)?'checked':''}> ${esc(v)}</label>`).join('')||'<small>Pas encore de référence.</small>'}</div><button type="button" class="btn sm secondary" data-action="addPicker:${kind}:${index}">＋ Ajouter</button></div>`
}
function sharedExperiences(){return state.experienceLibrary||=[]}
function copyExperience(x){return {...structuredClone(x),id:uid()}}
function groupById(id){return state.experienceGroups?.find(g=>g.id===id)}
function importVariant(g,v){active().experiences.push(variantForProject(g,v,uid()));update();note('Variante ajoutée au projet');}
function xpAssignments(setup){return Array.isArray(setup.assignments)&&setup.assignments.length?setup.assignments:[{experienceId:setup.experienceId,share:100,ticketPrice:setup.ticketPrice}];}
function periodResults(){return trafficPeriod.start||trafficPeriod.end?forecastTraffic(active(),trafficPeriod):results.traffic}
function action(label,code,cls='secondary'){return `<button class="btn ${cls}" data-action="${esc(code)}">${esc(label)}</button>`}
function card(title,content,right=''){return `<div class="card"><div class="cardTitle"><h2>${title}</h2>${right}</div>${content}</div>`}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="empty">Aucune donnée</td></tr>`}</tbody></table></div>`}
function kpi(label,value,hint=''){return `<div class="kpi"><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${hint}</div></div>`}
function summary(){const {traffic:t,staff:s,capex:c,finance:f}=results;return `<div class="grid">${kpi('Visiteurs prévisionnels',fmt(t.visitors),'85 % remplissage · 65 % de sessions par défaut')}${kpi('Chiffre d’affaires TTC',eur(t.gross),'Billetterie uniquement')}${kpi('OPEX calculés',eur(f.expenses),'Personnel, frais fixes, variables')}${kpi('Résultat d’exploitation',`<span class="${f.profit>=0?'green':'red'}">${eur(f.profit)}</span>`,'Avant financement et investissement')}</div><div class="grid">${kpi('CAPEX estimé',eur(c.cost),c.missing.length?`${c.missing.length} référence(s) sans prix`:'Prix historiques non actualisés')}${kpi('Sessions potentielles',fmt(t.potential),'Sur la période')}${kpi('Seuil d’équilibre',f.breakeven==null?'Non calculable':fmt(f.breakeven)+' visiteurs','Sur toute la période')}${kpi('Heures de personnel',fmt(s.hours,1)+' h','Pauses incluses automatiquement')}</div>`}
function chart(months){if(!months.length)return '<p class="muted">Choisissez une période valide pour afficher une courbe.</p>';const high=Math.max(1,...months.map(x=>x.visitors));return `<div class="chartWrap"><div class="chart">${months.map(m=>`<div class="col" title="${esc(m.month)} : ${fmt(m.visitors,1)} visiteurs" style="height:${Math.max(2,m.visitors/high*100)}%" data-label="${esc(m.month.slice(5))}"></div>`).join('')}</div></div>`}
function dashboard(){const t=results.traffic,f=results.finance;return `<p class="lead">Vue consolidée du projet <strong>${esc(active().name)}</strong>. Les données sont calculées localement et actualisées à chaque modification.</p>${summary()}<div class="two">${card('Fréquentation mensuelle',chart(t.monthly))}${card('Diagnostic rapide',`<p><span class="badge ${f.profit>=0?'good':'warn'}">${f.profit>=0?'Exploitation excédentaire':'Exploitation déficitaire'}</span></p><p>Objectif d’équilibre : <strong>${f.breakeven==null?'Indéterminé':fmt(f.breakeven)+' visiteurs'}</strong>.</p><p>Besoin moyen : <strong>${f.breakPerDay==null?'—':fmt(f.breakPerDay,1)+' / jour'}</strong>, <strong>${f.breakPerHour==null?'—':fmt(f.breakPerHour,1)+' / heure d’ouverture'}</strong>.</p><p class="muted xsmall">Ce seuil est indicatif et calculé sur la contribution moyenne ; les contrats complexes, flux de trésorerie et financements détaillés ne sont pas encore intégrés au moteur alpha.</p>${results.capex.missing.length?`<div class="notice warn"><strong>Prix à compléter :</strong> ${esc(results.capex.missing.join(', '))}</div>`:''}`)}</div>${card('Périmètre d’exploitation',table(['Lieu','Ouverture','Fin','Visiteurs','CA TTC'],t.byLocation.map(x=>{const loc=active().locations.find(l=>l.id===x.id);return `<tr><td>${esc(x.name)}</td><td>${esc(loc.startDate)}</td><td>${esc(loc.endDate)}</td><td>${fmt(x.visitors,1)}</td><td>${eur(x.gross)}</td></tr>`})))}<p class="muted xsmall">Attention : revenus, coûts et seuils sont des prévisions. Les prix catalogue importés sont historiques, et les coûts non renseignés restent signalés.</p>`}
function lifecyclePage(){
 const group=state.projectGroups.find(g=>g.id===selectedGroupId)||state.projectGroups.find(g=>g.id===active()?.groupId)||state.projectGroups[0];
 if(!group)return card('Dossiers',`<p>Aucun dossier créé.</p>${action('＋ Nouveau dossier','lifecycleNewGroup','primary')}`);
 const ops=groupOperations(state,group.id),summary=lifecycleSummary(state,group.id);
 const left=`<div class="lifecycle-groups">${state.projectGroups.map(g=>`<button class="lifecycle-group ${g.id===group.id?'selected':''}" data-action="lifecycleGroup:${g.id}"><strong>${esc(g.name)}</strong><small>${groupOperations(state,g.id).length} exploitation(s)</small></button>`).join('')}</div>`;
 const dev=group.development||{};
 return `<div class="toolbar">${action('＋ Nouveau dossier','lifecycleNewGroup','primary')}${action('＋ Nouvelle exploitation','lifecycleBlank:'+group.id,'secondary')}${action('Associer une exploitation existante','lifecycleAttach:'+group.id,'ghost')}${ops.length?action('Dupliquer une exploitation','lifecycleCopy:'+group.id,'ghost'):''}</div><div class="lifecycle-layout"><aside class="card">${left}</aside><div><div class="card"><span class="eyebrow">DOSSIER GLOBAL</span><h2>${esc(group.name)}</h2><p class="muted">${summary.operations} exploitation(s) · ${summary.locations} lieu(x) · ${summary.experiences} expérience(s) référencée(s)</p><div class="formGrid">${field('Nom du dossier','group.'+group.id+'.name',group.name)}${check('Activer la phase de développement','group.'+group.id+'.development.enabled',dev.enabled)}</div><div class="notice">Les simulations existantes demeurent indépendantes. Un dossier regroupe les phases sans modifier leurs moteurs financiers.</div></div>
 <div class="card"><div class="cardTitle"><h2>① Phase développement</h2><span class="badge">À compléter dans une version future</span></div>${dev.enabled?`<p>La phase est activée. Les coproducteurs, budgets et droits seront ajoutés dans le futur module Développement.</p><div class="formGrid">${field('Notes de développement','group.'+group.id+'.development.notes',dev.notes||'')}</div>`:'<p class="muted">Phase facultative. Activez-la si le dossier inclut une création ou une coproduction.</p>'}</div>
 <div class="card"><div class="cardTitle"><h2>② Exploitations</h2><span class="badge good">${ops.length} exploitation(s)</span></div><div class="lifecycle-operations">${ops.map((op,i)=>`<div class="lifecycle-operation"><div><strong>${esc(op.operationLabel||op.name)}</strong><small>${(op.locations||[]).length} lieu(x) · ${(op.experiences||[]).length} expérience(s)</small></div><div class="toolbar">${action('Ouvrir →','lifecycleOpen:'+op.id,'sm primary')}${action('Dupliquer','lifecycleCopyOne:'+op.id,'sm secondary')}</div></div>`).join('')||'<p class="muted">Aucune exploitation. Créez-en une pour démarrer les prévisions.</p>'}</div><div class="toolbar">${action('＋ Nouvelle exploitation vierge','lifecycleBlank:'+group.id,'primary')}${ops.length?action('Dupliquer une exploitation','lifecycleCopy:'+group.id,'secondary'):''}</div></div>
 <div class="card"><h2>Expériences liées au dossier</h2><p class="muted">Références présentes dans les exploitations (un lien détaillé avec la bibliothèque commune est prévu pour la V1.9.2).</p>${[...new Set(ops.flatMap(op=>(op.experiences||[]).map(x=>x.name)))].map(name=>`<span class="badge" style="margin:4px">${esc(name)}</span>`).join('')||'—'}</div></div></div>`;
}
function projects(){return `<div class="toolbar">${action('＋ Nouveau projet','newProject')}${action('Dupliquer le projet','duplicateProject')}${action('＋ Enregistrer scénario','newScenario','ghost')}${action('Comparer les scénarios','compareScenarios','ghost')}</div>${card('Identité du projet',`<div class="formGrid">${field('Nom','project.name',active().name)}${choice('Devise du projet','project.currency',active().currency||'EUR',['EUR','USD','GBP','TWD','JPY','CHF'])}${field('Identifiant (lecture seule)','project.id',active().id,'text','readonly')}</div>`)}${card('Projets enregistrés',table(['Nom','Lieux','Expériences','Actions'],state.projects.map(p=>`<tr><td><strong>${esc(p.name)}</strong> ${p.id===state.activeId?'<span class="badge good">Actif</span>':''}</td><td>${p.locations?.length||0}</td><td>${p.experiences?.length||0}</td><td class="actions">${action('Ouvrir','project:'+p.id,'sm secondary')} ${action('Supprimer','deleteProject:'+p.id,'sm danger')}</td></tr>`)))}${card('Scénarios enregistrés',table(['Nom','Projet','Date','Actions'],state.scenarios.map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.project.name)}</td><td>${esc(s.date?.slice(0,10))}</td><td class="actions">${action('Charger','loadScenario:'+s.id,'sm secondary')} ${action('Exporter JSON','exportScenario:'+s.id,'sm ghost')} ${action('Supprimer','deleteScenario:'+s.id,'sm danger')}</td></tr>`)))}`}
function experienceLibraryPage(){
 const groups=state.experienceGroups||[];
 const filtered=groups.filter(g=>g.title.toLowerCase().includes(xpLibrarySearch.toLowerCase()));
 const poster=g=>g.poster?`<img src="${esc(g.poster)}" alt="Affiche ${esc(g.title)}">`:`<div class="xp-poster-placeholder">◈<span>VISUEL À AJOUTER</span></div>`;
 const cards=filtered.map(g=>`<article class="xp-library-card"><div class="xp-card-image">${poster(g)}</div><div class="xp-card-content"><h3>${esc(g.title)}</h3><p>${g.variants.length} variante(s)</p><p class="muted xsmall">${esc(g.description||'')}</p>${action('Ouvrir la fiche','openXpGroup:'+g.id,'sm secondary')}</div></article>`).join('')||'<p class="muted">Aucune expérience correspondante.</p>';
 const current=groupById(selectedExperienceGroup);
 let edit='';
 if(current){const gi=groups.indexOf(current);
 const opts=current.variants.map((v,j)=>`<details class="xp-variant" ${j===0?'open':''}><summary>${esc(v.label||v.version||'Format standard')} · ${esc(v.capacity??'?')} joueur(s)</summary><div class="formGrid">${field('Nom de la variante',`experienceGroups.${gi}.variants.${j}.label`,v.label||v.version||'')}${field('Capacité par session',`experienceGroups.${gi}.variants.${j}.capacity`,v.capacity,'number','min="1"')}${field('Cadence de référence (sessions/h)',`experienceGroups.${gi}.variants.${j}.sessionsPerHourReference`,v.sessionsPerHourReference??'','number','min="0" step="0.01"')}${field('Durée de jeu (min)',`experienceGroups.${gi}.variants.${j}.duration`,v.duration??'','number','min="0" step="0.1"')}${field('Battement (min)',`experienceGroups.${gi}.variants.${j}.turnaround`,v.turnaround??'','number','min="0" step="0.1"')}${field('Prix billet conseillé TTC',`experienceGroups.${gi}.variants.${j}.ticketPrice`,v.ticketPrice??'','number','min="0" step="0.01"')}${field('Largeur (m)',`experienceGroups.${gi}.variants.${j}.playWidthM`,v.playWidthM??'','number','min="0" step="0.1"')}${field('Profondeur (m)',`experienceGroups.${gi}.variants.${j}.playDepthM`,v.playDepthM??'','number','min="0" step="0.1"')}${choice('Mode VR',`experienceGroups.${gi}.variants.${j}.mode`,v.mode||'Standalone',['PCVR','Standalone'])}${field('Opérateurs/setup',`experienceGroups.${gi}.variants.${j}.operatorsRatio`,v.operatorsRatio??'','number','min="0" step="0.1"')}</div><div class="toolbar">${action('Ajouter cette variante au projet','useXpVariant:'+gi+':'+j,'sm primary')}${action('Dupliquer la variante','duplicateXpVariant:'+gi+':'+j,'sm secondary')}${action('Supprimer la variante','deleteXpVariant:'+gi+':'+j,'sm danger')}</div></details>`).join('');
 edit=`<div class="card xp-group-detail"><div class="split"><h2>${esc(current.title)}</h2>${action('Fermer ✕','closeXpGroup','sm ghost')}</div><div class="xp-detail-head"><div class="xp-detail-image">${poster(current)}</div><div><div class="formGrid">${field('Titre de l’expérience',`experienceGroups.${gi}.title`,current.title)}${field('Description',`experienceGroups.${gi}.description`,current.description||'')}</div><label class="btn sm secondary" for="xpPosterUpload">⇧ Importer une affiche (PNG, JPG ou WebP)</label><input type="file" id="xpPosterUpload" accept="image/png,image/jpeg,image/webp" hidden data-group="${esc(current.id)}"><p class="muted xsmall">Image enregistrée localement dans les données. Taille maximum : 500 Ko. Sauvegarde JSON comprise.</p>${current.poster?action('Supprimer l’affiche','deleteXpPoster:'+gi,'sm ghost'):''}</div></div><h3>Variantes d’exploitation</h3>${opts}<div class="toolbar">${action('＋ Nouvelle variante','addXpVariant:'+gi,'secondary')}</div></div>`;
 }
 return `<div class="xp-library-intro"><div><h2>Catalogue d’expériences</h2><p class="muted">Une fiche et une affiche par expérience, plusieurs formats d’exploitation.</p></div>${action('＋ Nouvelle fiche','createXpGroup','primary')}</div><div class="toolbar"><input id="xpLibrarySearch" placeholder="Rechercher une expérience…" value="${esc(xpLibrarySearch)}" aria-label="Rechercher dans la bibliothèque"></div><div class="xp-library-grid">${cards}</div>${edit}`;
}
function experiences(){
 const p=active();
 const headsetOptions=[...new Set(['HTC Focus 3','HTC Focus Vision','Pico 4 Ultra Enterprise',...p.experiences.flatMap(x=>x.compatibleHeadsets||[])])];
 const equipmentOptions=[...new Set([...state.catalog.map(x=>x.name),...p.experiences.flatMap(x=>x.extraEquipment||[])])];
 const partnerOptions=[...new Set(p.experiences.flatMap(x=>x.coproducers||[]))];
 let out=experienceLibraryPage()+`<div class="sectionTitle borderTop">EXPÉRIENCES DU PROJET ACTIF</div><p class="muted">Ces paramètres sont une copie indépendante de ceux du catalogue.</p><div class="toolbar">${action('＋ Ajouter une expérience','addExperience')}${action('⇩ Importer depuis bibliothèque','importExperience','secondary')}</div><p class="muted xsmall">Les références de la bibliothèque sont partagées entre projets. Une expérience importée est une copie modifiable sans affecter les autres projets.</p>`;
 p.experiences.forEach((x,i)=>{
  const controls=[
   field('Nom',`experiences.${i}.name`,x.name),
   choice('Type',`experiences.${i}.mode`,x.mode,['PCVR','Standalone']),
   field('Capacité / session',`experiences.${i}.capacity`,x.capacity,'number','min="1"'),
   field('Durée session (min)',`experiences.${i}.duration`,x.duration,'number','min="1"'),
   field('Intervalle entre lancements (min)',`experiences.${i}.turnaround`,turnaround(x),'number','min="0"'),
   field('Billet TTC indicatif (€)',`experiences.${i}.ticketPrice`,x.ticketPrice,'number','min="0" step="0.01"'),
   field('Ratio opérateurs / setup',`experiences.${i}.operatorsRatio`,x.operatorsRatio??.6,'number','min="0" step="0.1"'),
   multiPicker('Casques compatibles','compatibleHeadsets',x.compatibleHeadsets||[],i,headsetOptions),
   `<div class="dimension-group"><div class="sectionTitle">ESPACE DE JEU REQUIS ${help('Dimensions minimales de la zone de jeu, hors zones d’accueil et de circulation.')}</div><div class="dimension-row">${field('Largeur (m)',`experiences.${i}.playWidthM`,x.playWidthM??'','number','min="0" step="0.1"')}${field('Profondeur (m)',`experiences.${i}.playDepthM`,x.playDepthM??'','number','min="0" step="0.1"')}</div><p class="dimension-summary">${num(x.playWidthM)>0&&num(x.playDepthM)>0?`Espace requis : ${fmt(num(x.playWidthM),1)} × ${fmt(num(x.playDepthM),1)} m — ${fmt(num(x.playWidthM)*num(x.playDepthM),2)} m²`:'Renseignez les deux dimensions pour calculer la surface.'}</p></div>`
  ];
  const advanced=`<details><summary>Paramètres détaillés · coproducteurs et équipements</summary><div class="formGrid">${multiPicker('Matériel complémentaire','extraEquipment',x.extraEquipment||[],i,equipmentOptions)}${multiPicker('Coproducteurs','coproducers',x.coproducers||[],i,partnerOptions)}</div></details>`;
  const buttons=`<div class="footerActions">${action('Enregistrer dans la bibliothèque','saveExperience:'+i,'secondary')}${action('Dupliquer','duplicateExperience:'+i,'ghost')}${action('Supprimer','deleteExperience:'+i,'danger')}</div>`;
  out+=card(`Expérience ${i+1} · ${esc(x.name)}`,`<div class="formGrid">${controls.join('')}</div>${advanced}${buttons}`);
 });
 return out;
}
function operations(){
 const p=active();let out=`<div class="toolbar">${action('＋ Ajouter un lieu','addLocation')}</div><div class="notice">Un setup peut accueillir plusieurs expériences, avec une répartition du temps et un prix par expérience.</div>`;
 p.locations.forEach((loc,i)=>{
  const locationFields=`<div class="formGrid">${field('Nom du lieu',`locations.${i}.name`,loc.name)}${field('Début',`locations.${i}.startDate`,loc.startDate,'date')}${field('Fin',`locations.${i}.endDate`,loc.endDate,'date')}</div>`;
  const hours=table(['Jour','Ouvert','De (HH:MM)','À (HH:MM)','Recopier les horaires'],weekNames.map((day,d)=>`<tr><td>${day}</td><td>${check('',`locations.${i}.week.${d}.open`,loc.week[d].open)}</td><td>${hourInput(`locations.${i}.week.${d}.start`,loc.week[d].start)}</td><td>${hourInput(`locations.${i}.week.${d}.end`,loc.week[d].end)}</td><td><select class="copy-day" data-location="${i}" data-day="${d}" aria-label="Copier les horaires de ${day}"><option value="">Copier vers…</option>${weekNames.map((name,n)=>n===d?'':`<option value="${n}">${name}</option>`).join('')}<option value="all">Tous les autres jours</option></select></td></tr>`));
  const exceptions=table(['Début','Fin','Fermé','Ouverture','Fermeture',''],(loc.exceptions||[]).map((e,j)=>`<tr><td><input type="date" data-bind="locations.${i}.exceptions.${j}.from" value="${esc(e.from)}"></td><td><input type="date" data-bind="locations.${i}.exceptions.${j}.to" value="${esc(e.to)}"></td><td>${check('',`locations.${i}.exceptions.${j}.closed`,e.closed)}</td><td>${hourInput(`locations.${i}.exceptions.${j}.start`,e.start||'10:00')}</td><td>${hourInput(`locations.${i}.exceptions.${j}.end`,e.end||'18:00')}</td><td>${action('✓ Valider',`validateException:${i}`,'sm secondary')} ${action('×',`deleteException:${i}:${j}`,'sm danger')}</td></tr>`));
  let rooms='';
  (loc.rooms||[]).forEach((room,j)=>{
   let setups='';
   (room.setups||[]).forEach((setup,k)=>{
    const pre=`locations.${i}.rooms.${j}.setups.${k}`,assignments=xpAssignments(setup);
    const setupFields=`<div class="formGrid">${field('Nom du setup',`${pre}.name`,setup.name)}${choice('Mode',`${pre}.mode`,setup.mode,['PCVR','Standalone'])}${choice('Casque / modèle',`${pre}.headsetModel`,setup.headsetModel||'',[['','À définir'],...[...new Set([...state.catalog.filter(v=>v.category==='Casque VR').map(v=>v.name),...p.experiences.flatMap(v=>v.compatibleHeadsets||[]),setup.headsetModel].filter(Boolean))]])}${field('Casques par setup',`${pre}.headsets`,setup.headsets??12,'number','min="1"')}${field('Casques déjà installés par setup',`${pre}.installedHeadsets`,setup.installedHeadsets??0,'number','min="0"')}${field('Nombre de setups identiques',`${pre}.count`,setup.count??1,'number','min="1"')}${field('Capacité par lancement',`${pre}.capacity`,setup.capacity??setup.headsets??10,'number','min="1"')}${field('Largeur de jeu disponible (m)',`${pre}.playWidthM`,setup.playWidthM??'','number','min="0" step="0.1"')}${field('Profondeur de jeu disponible (m)',`${pre}.playDepthM`,setup.playDepthM??'','number','min="0" step="0.1"')}</div>`;
    const assignmentRows=assignments.map((a,n)=>{
     const opts=p.experiences.map(x=>{const fit=setupExperienceFit(x,setup);return `<option value="${esc(x.id)}" ${a.experienceId===x.id?'selected':''} ${!fit.compatible&&a.experienceId!==x.id?'disabled':''}>${esc(x.name)}${!fit.compatible?' ⚠ incompatible':fit.unknown?' · à vérifier':''}</option>`}).join('');
     const rate=esc(a.share),price=esc(a.ticketPrice??p.experiences.find(x=>x.id===a.experienceId)?.ticketPrice??35);
     const remove=assignments.length>1?action('×',`removeAssignment:${i}:${j}:${k}:${n}`,'sm danger'):'';
     return `<tr><td><select data-bind="${pre}.assignments.${n}.experienceId">${opts}</select></td><td><input type="number" min="0" max="100" step="0.01" data-bind="${pre}.assignments.${n}.share" value="${rate}"></td><td><input type="number" min="0" step=".01" data-bind="${pre}.assignments.${n}.ticketPrice" value="${price}"></td><td>${remove}</td></tr>`;
    });
    const assignmentTable=table(['Expérience','Part des créneaux (%)','Prix billet TTC (€)',''],assignmentRows);
    setups+=`<div class="card setup-card"><div class="split"><strong>${esc(setup.name)}</strong>${action('Supprimer ce setup',`deleteSetup:${i}:${j}:${k}`,'sm danger')}</div>${setupFields}<div class="sectionTitle">Expériences sur ce setup ${help('Une expérience occupe une fraction des créneaux du même setup physique, sans augmenter sa capacité.')}</div>${assignmentTable}<div class="toolbar">${action('＋ Ajouter expérience',`addAssignment:${i}:${j}:${k}`,'sm secondary')}</div><small>Installation : ${installationRequirement(setup).toInstall} casques à installer · ${installationRequirement(setup).installed} déjà installés. Répartition totale : ${fmt(assignments.reduce((sum,a)=>sum+num(a.share),0),2)} % · ajustement automatique des autres parts lors d'une modification.</small></div>`;
   });
   rooms+=`<div class="card" style="background:#f9fbfe"><div class="split"><h3>${esc(room.name)}</h3>${action('Dupliquer la salle',`duplicateRoom:${i}:${j}`,'sm secondary')} ${action('Supprimer salle',`deleteRoom:${i}:${j}`,'sm danger')}</div><div class="formGrid">${field('Nom salle',`locations.${i}.rooms.${j}.name`,room.name)}</div>${setups}<div class="toolbar borderTop">${action('＋ Ajouter setup',`addSetup:${i}:${j}`,'sm secondary')}</div></div>`;
  });
  out+=card(`Lieu ${i+1} · ${esc(loc.name)}`,`${locationFields}<div class="sectionTitle">Horaires habituels</div>${hours}<details id="exceptions-${i}"><summary>Exceptions et fermetures particulières (${(loc.exceptions||[]).length})</summary><div class="toolbar">${action('＋ Ajouter exception',`addException:${i}`,'sm secondary')}</div>${exceptions}</details><div class="sectionTitle borderTop">Salles</div>${rooms}<div class="toolbar">${action('＋ Ajouter salle',`addRoom:${i}`,'sm secondary')}${action('Supprimer lieu',`deleteLocation:${i}`,'sm danger')}</div>`);
 });
 return out;
}
function traffic(){const t=periodResults(),p=active();const dates=p.locations.map(x=>x.startDate).filter(Boolean).sort(),ends=p.locations.map(x=>x.endDate).filter(Boolean).sort();return `<div class="formGrid">${field('Taux de sessions jouées (%)','settings.sessionRatePercent',num(p.settings.sessionRate,.65)*100,'number','min="0" max="100" step="1"')}${field('Remplissage des groupes (%)','settings.fillRatePercent',num(p.settings.fillRate,.85)*100,'number','min="0" max="100" step="1"')}</div>${card('Période consultée',`<div class="formGrid"><div class="field"><label>Du</label><input type="date" data-period="start" value="${esc(trafficPeriod.start||dates[0]||'')}"></div><div class="field"><label>Au</label><input type="date" data-period="end" value="${esc(trafficPeriod.end||ends.at(-1)||'')}"></div></div><div class="toolbar">${action('Toute la période','resetPeriod','sm secondary')}${action('Exporter la période CSV','exportTraffic','sm secondary')}</div>`)}<div class="grid">${kpi('Sessions potentielles',fmt(t.potential,1))}${kpi('Visiteurs prévisionnels',fmt(t.visitors,1))}${kpi('CA maximal TTC',eur(t.maxGross))}${kpi('CA estimé TTC',eur(t.gross))}</div>${card('Résultats mensuels',table(['Période','Jours ouverts','Sessions possibles','Sessions jouées','Visiteurs','CA maximal TTC','CA estimé TTC'],t.monthly.map(m=>`<tr><td>${esc(m.month)}</td><td>${m.openDays}</td><td>${fmt(m.potential,1)}</td><td>${fmt(m.played,1)}</td><td><strong>${fmt(m.visitors,1)}</strong></td><td>${eur(m.maxGross)}</td><td>${eur(m.gross)}</td></tr>`)))}${card('Détail des calculs',`<p class="muted xsmall">Créneaux disponibles = 1 + ⌊(ouverture − durée de partie) / (durée de partie + battement)⌋, uniquement si la partie finit avant fermeture. Les créneaux sont répartis entre les expériences du même setup, sans duplication physique.</p><details><summary>Voir les lignes quotidiennes (${t.lines.length})</summary>${table(['Date','Lieu','Setup','Expérience','Part','Visiteurs','CA max TTC','CA estimé TTC'],t.lines.slice(0,500).map(x=>`<tr><td>${x.date}</td><td>${esc(x.location)}</td><td>${esc(x.setup)}</td><td>${esc(x.experience)}</td><td>${fmt(x.share*100,1)} %</td><td>${fmt(x.visitors,1)}</td><td>${eur(x.maxGross)}</td><td>${eur(x.gross)}</td></tr>`))}${t.lines.length>500?'<p class="muted">500 premières lignes affichées. Exporter le CSV pour tout voir.</p>':''}</details>`)}`}
function staff(){const p=active(),s=p.staff,x=results.staff;return `${card('Personnel — Paramètres',`<div class="formGrid">${field('Opérateurs par setup',`staff.operatorsPerSetup`,s.operatorsPerSetup,'number','step="0.1" min="0"')}${field('Personnel accueil par lieu',`staff.reception`,s.reception,'number','min="0"')}${field('Coût chargé horaire (€)',`staff.hourlyCost`,s.hourlyCost,'number','min="0" step="0.01"')}${field('Préparation (min)',`staff.beforeMinutes`,s.beforeMinutes,'number','min="0"')}${field('Fermeture (min)',`staff.afterMinutes`,s.afterMinutes,'number','min="0"')}${field('Pause par salarié (min)',`staff.pauseMinutes`,s.pauseMinutes,'number','min="0"')}${field('Seuil pour pause (heures)',`staff.pauseThresholdHours`,s.pauseThresholdHours,'number','min="0"')}</div>${check('Couverture des pauses avec des heures de renfort (par défaut)',`staff.pauseCoverage`,s.pauseCoverage)}<details><summary>Options avancées : effectif présent avant / après</summary><div class="formGrid">${field('Opérateurs avant ouverture (laisser vide = toute équipe)','staff.beforeOperators',s.beforeOperators??'','number','min="0"')}${field('Opérateurs après fermeture','staff.afterOperators',s.afterOperators??'','number','min="0"')}</div></details>`)}<div class="grid">${kpi('Heures de présence',fmt(x.shiftHours,1)+' h')}${kpi('Renfort pauses',fmt(x.pauseHours,1)+' h')}${kpi('Total heures facturées',fmt(x.hours,1)+' h')}${kpi('Coût personnel',eur(x.cost))}</div>${card('Personnel complémentaire',`${table(['Poste','Mode','Personnes','Heures','Coût horaire','Coût global',''],(s.extraStaff||[]).map((v,i)=>`<tr><td><input data-bind="staff.extraStaff.${i}.name" value="${esc(v.name)}"></td><td><select data-bind="staff.extraStaff.${i}.mode"><option value="hourly" ${v.mode!=='fixed'?'selected':''}>Horaire</option><option value="fixed" ${v.mode==='fixed'?'selected':''}>Forfait</option></select></td><td><input type="number" data-bind="staff.extraStaff.${i}.people" value="${esc(v.people??1)}"></td><td><input type="number" data-bind="staff.extraStaff.${i}.hours" value="${esc(v.hours??0)}"></td><td><input type="number" data-bind="staff.extraStaff.${i}.rate" value="${esc(v.rate??0)}"></td><td><input type="number" data-bind="staff.extraStaff.${i}.amount" value="${esc(v.amount??0)}"></td><td>${action('×','deleteExtra:'+i,'sm danger')}</td></tr>`))}<div class="toolbar borderTop">${action('＋ Ajouter formation / installation / responsable','addExtra','sm secondary')}</div>`)}${card('Dépenses OPEX',`${table(['Dépense','Montant (€)','Fréquence',''],(p.finance.opex||[]).map((v,i)=>`<tr><td><input data-bind="finance.opex.${i}.name" value="${esc(v.name)}"></td><td><input type="number" data-bind="finance.opex.${i}.amount" value="${esc(v.amount)}"></td><td><select data-bind="finance.opex.${i}.frequency">${['daily','weekly','monthly','once'].map(k=>`<option value="${k}" ${v.frequency===k?'selected':''}>${{daily:'Jour',weekly:'Semaine',monthly:'Mois',once:'Une fois'}[k]}</option>`).join('')}</select></td><td>${action('×','deleteOpex:'+i,'sm danger')}</td></tr>`))}<div class="toolbar borderTop">${action('＋ Ajouter dépense','addOpex','sm secondary')}</div>`)}<p class="muted xsmall">Les pauses sont prises en compte automatiquement comme renfort théorique. Les règles de droit du travail et plannings réels sont à vérifier selon l'organisation.</p>`}
function catalog(){return `<p class="lead">Catalogue importé du classeur « Liste matos.xlsx » : ${state.catalog.length} références. Les liens, prix et caractéristiques peuvent être modifiés. Les prix historiques ne sont pas actualisés automatiquement.</p><div class="toolbar">${action('＋ Ajouter une référence','addCatalog')}${action('Exporter catalogue CSV','exportCatalog','secondary')}</div>${card('Bibliothèque matériel',table(['Référence','Catégorie','Prix achat HT (€)','Statut','Fournisseur / lien',''],state.catalog.map((x,i)=>`<tr><td><input data-bind="catalog.${i}.name" value="${esc(x.name)}" style="min-width:230px"></td><td><input data-bind="catalog.${i}.category" value="${esc(x.category||'')}"></td><td><input type="number" step="0.01" data-bind="catalog.${i}.price" value="${x.price==null?'':esc(x.price)}" placeholder="À vérifier"></td><td><select data-bind="catalog.${i}.status">${['à compléter','à vérifier','validé','obsolète'].map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`).join('')}</select></td><td><input type="url" data-bind="catalog.${i}.url" value="${esc(x.url||'')}" placeholder="https://…"><small>${esc(x.source||'')} ${x.url?.startsWith('https://')||x.url?.startsWith('http://')?`· <a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Ouvrir ↗</a>`:''}</small></td><td>${action('×',`deleteCatalog:${i}`,'sm danger')}</td></tr>`)))}<p class="muted xsmall">Les prix manquants sont intentionnellement exclus des totaux et signalés ; ils ne sont pas assimilés à zéro. Les modèles importés restent accessibles dans les données du projet.</p>`}
function capex(){const p=active(),c=results.capex,ovs=p.capex.overrides||{};
 return `<div class="grid">${kpi('Investissement neuf HT',eur(c.purchase),'Achat uniquement')}${kpi('Location HT',eur(c.rental),'Durée définie par ligne')}${kpi('Coût d’utilisation stock HT',eur(c.stockUse),'Valorisation facultative')}${kpi('Coût matériel du projet HT',eur(c.totalCost),'Hors montants non renseignés')}</div>
 ${card('Dimensionnement',`<div class="grid">${kpi('Casques',fmt(c.devices))}${kpi('PC clients + serveurs',c.pc+' + '+c.servers)}${kpi('AP Wi-Fi',fmt(c.ap))}${kpi('Setups',fmt(c.sets))}</div>`)}
 ${card('Règles et prix de vente',`<div class="formGrid">${field('Marge sur prix de vente (%)','capex.marginPercent',num(p.capex.margin,.3)*100,'number','min="0" max="95"')}${field('Capacité chargeur (batteries)','settings.chargerCapacity',p.settings.chargerCapacity||2,'number','min="1"')}${field('Zones techniques','capex.technicalZones',p.capex.technicalZones||1,'number','min="1"')}</div><div class="notice">Pour chaque ligne, choisissez une quantité en stock et une quantité louée. Le reste est acheté. Les coûts de stock et de location sont configurables et ne sont pas assimilés à du CAPEX.</div>`)}
 ${card('Répartition du matériel · achat / stock / location',`${table(['Référence','Qté requise','Qté retenue','Stock','Déjà installés','Location','À acheter','PU achat HT','Coût stock / unité HT','Location / unité / mois HT','Mois','Coût total HT','Marge %','Exclu'],c.items.map(x=>{const ov=ovs[x.id]||{};const bind=(k)=>'capex.overrides.'+esc(x.id)+'.'+k;return `<tr><td><strong>${esc(x.name)}</strong><br><small class="muted">${esc(x.reason)}</small></td><td>${fmt(x.originalQty)}</td><td><input type="number" min="0" data-bind="${bind('qty')}" value="${ov.qty??''}" placeholder="${x.originalQty}" style="width:75px"></td><td><input type="number" min="0" data-bind="${bind('stockQty')}" value="${ov.stockQty??x.stockQty??0}" style="width:70px"></td><td><input type="number" min="0" data-bind="${bind('installedQty')}" value="${ov.installedQty??x.installedQty??0}" style="width:70px"></td><td><input type="number" min="0" data-bind="${bind('rentQty')}" value="${ov.rentQty??0}" style="width:70px"></td><td><strong>${x.buyQty}</strong></td><td><input type="number" min="0" step=".01" data-bind="${bind('unitCost')}" value="${ov.unitCost??x.unitCost??''}" placeholder="À vérifier" style="width:95px"></td><td><input type="number" min="0" step=".01" data-bind="${bind('stockUnitCost')}" value="${ov.stockUnitCost??0}" style="width:95px"></td><td><input type="number" min="0" step=".01" data-bind="${bind('rentalUnitCost')}" value="${ov.rentalUnitCost??''}" placeholder="À renseigner" style="width:100px"></td><td><input type="number" min="1" step="1" data-bind="${bind('rentalMonths')}" value="${ov.rentalMonths??1}" style="width:58px"></td><td>${eur(x.total)} ${x.total==null?'<span class="badge warn">Incomplet</span>':''}</td><td><input type="number" min="0" max="95" data-bind="${bind('marginPercent')}" value="${ov.margin!=null?fmt(ov.margin*100):''}" placeholder="${fmt(num(p.capex.margin,.3)*100)}" style="width:75px"></td><td>${check('',bind('excluded'),ov.excluded)}</td></tr>`}))}
 <div class="toolbar borderTop">${action('Réinitialiser les ajustements','clearOverrides','sm ghost')}${action('Exporter vue interne CSV','exportCapex','sm secondary')}${action('Exporter devis client CSV','exportClientQuote','sm secondary')}${action('Imprimer devis client','printClientQuote','sm secondary')}${action('Imprimer vue interne','printCapex','sm secondary')}${action('Créer un devis personnalisable','quoteOpen','sm primary')}</div>
 <div class="split"><strong>Achat neuf : ${eur(c.purchase)}</strong><strong>Coûts complets : ${eur(c.totalCost)}</strong><strong>Devis client HT : ${eur(c.sale)}</strong></div>
 ${c.missing.length?`<div class="notice warn">Coûts manquants : ${esc(c.missing.join(', '))}. Un montant manquant n'est jamais considéré comme zéro pour le devis.</div>`:''}`)}
 ${card('Autres lignes complémentaires (ne pas dupliquer les missions)',`${table(['Libellé','Quantité','Coût unitaire HT','Catégorie',''],(p.capex.custom||[]).map((x,i)=>`<tr><td><input data-bind="capex.custom.${i}.name" value="${esc(x.name)}"></td><td><input type="number" data-bind="capex.custom.${i}.qty" value="${esc(x.qty)}"></td><td><input type="number" step=".01" data-bind="capex.custom.${i}.unitCost" value="${esc(x.unitCost??'')}"></td><td><input data-bind="capex.custom.${i}.category" value="${esc(x.category)}"></td><td>${action('×','deleteCapex:'+i,'sm danger')}</td></tr>`))}<div class="toolbar borderTop">${action('＋ Ajouter une ligne','addCapex','sm secondary')}</div><p class="muted xsmall">Cette étape permet les prestations en lignes manuelles. Utiliser le module Prestations & logistique pour les missions détaillées ; ne pas saisir deux fois les mêmes coûts.</p>`)}
 <div class="notice">Le devis client montre le prix de vente, sans tarifs fournisseurs ni coût de revient. Les coûts non renseignés doivent être complétés avant émission.</div>`;
}

function missionTemplateManager(){
 const templates=state.missionTemplates||[];
 return `<div class="mission-template-manager">
  <p class="muted">Bibliothèque commune à tous les projets. Modifier un modèle ne change pas les missions déjà ajoutées à un projet.</p>
  <div class="toolbar">${action('＋ Créer un modèle','templateCreate','sm primary')}${action('Fermer la bibliothèque','templateManagerToggle','sm secondary')}</div>
  ${templates.length?templates.map((t,i)=>`<details class="mission"><summary><strong>${esc(t.name||'Modèle sans nom')}</strong> · ${esc(({before:'Avant ouverture',during:'Pendant exploitation',after:'Après exploitation'})[t.phase]||'Avant ouverture')}</summary>
    <div class="formGrid">${field('Nom du modèle',`missionTemplates.${i}.name`,t.name||'')}${choice('Secteur / catégorie',`missionTemplates.${i}.sector`,t.sector||'Prestations techniques',[['Prestations techniques','Prestations techniques'],['Formation','Formation'],['Logistique','Logistique'],['Maintenance','Maintenance'],['Production','Production'],['Autres','Autres']])}${choice('Phase',`missionTemplates.${i}.phase`,t.phase||'before',[['before','Avant ouverture'],['during','Pendant exploitation'],['after','Après exploitation']])}${field('Payeur / responsable',`missionTemplates.${i}.owner`,t.owner||'Backlight')}${check('Refacturable',`missionTemplates.${i}.billable`,t.billable!==false)}
    ${field('Techniciens',`missionTemplates.${i}.technicians`,t.technicians??1,'number','min="0" step="1"')}${field('Jours par technicien',`missionTemplates.${i}.days`,t.days??1,'number','min="0" step="0.5"')}${field('Heures / jour',`missionTemplates.${i}.hoursPerDay`,t.hoursPerDay??8,'number','min="0" step="0.5"')}${field('Coût horaire HT',`missionTemplates.${i}.hourlyCost`,t.hourlyCost??0,'number','min="0" step="0.01"')}${field('Marge (%)',`missionTemplates.${i}.marginPercent`,t.marginPercent??'','number','min="0" max="95" step="1"')}${field('Prix de vente fixe HT',`missionTemplates.${i}.salePrice`,t.salePrice??'','number','min="0" step="0.01"')}</div>
    <div class="toolbar">${action('Dupliquer ce modèle','templateDuplicate:'+i,'sm secondary')}${action('Supprimer ce modèle','templateDelete:'+i,'sm danger')}</div></details>`).join(''):'<div class="notice">Aucun modèle enregistré. Créez-en un ou utilisez « Enregistrer comme modèle » depuis une mission.</div>'}
 </div>`;
}
function deployment(){
 const p=active(),d=p.deployment||{},r=results.deployment,templates=state.missionTemplates||[];
 const phaseOpts=[['before','Avant ouverture'],['during','Pendant l’exploitation'],['after','Après exploitation']];
 const rows=(d.missions||[]).map((m,i)=>{
  const base=`deployment.missions.${i}.`;
  const f=(label,key,step='0.01')=>field(label,base+key,m[key]??'','number',`min="0" step="${step}"`);
  return `<details class="mission"><summary><strong>${esc(m.name||'Nouvelle mission')}</strong> · ${esc(({before:'Avant',during:'Pendant',after:'Après'})[m.phase]||'Avant')} · ${eur(r.items[i]?.cost||0)} HT</summary>
   <div class="formGrid">${field('Intitulé',base+'name',m.name||'')}${choice('Secteur commercial',base+'sector',m.sector||'Prestations techniques',[['Prestations techniques','Prestations techniques'],['Formation','Formation'],['Logistique','Logistique'],['Maintenance','Maintenance'],['Production','Production'],['Autres','Autres']])}${choice('Période de prise en charge',base+'phase',m.phase||'before',phaseOpts)}${field('Responsable / payeur',base+'owner',m.owner||'Backlight')}${check('Refacturer au client',base+'billable',m.billable!==false)}
   ${f('Techniciens', 'technicians','1')}${f('Journées par technicien','days','0.5')}${f('Heures par jour','hoursPerDay','0.5')}${f('Coût horaire chargé HT (€)','hourlyCost')}
   ${f('Heures de préparation atelier','preparationHours','0.5')}${f('Coût horaire préparation HT (€)','preparationHourlyCost')}
   ${f('Voyageurs','travelers','1')}${f('Transport A/R par personne HT (€)','transportPerPerson')}${f('Nuits par personne','nights','1')}${f('Hébergement / nuit HT (€)','hotelPerNight')}${f('Jours de repas / personne','mealDays','1')}${f('Repas / jour HT (€)','mealPerDay')}
   ${f('Transport local total HT (€)','localTransport')}${f('Expédition / fret HT (€)','freight')}${f('Douanes HT (€)','customs')}${f('Assurance transport HT (€)','insurance')}${f('Autres frais HT (€)','otherCost')}${field('Marge de vente (%) · vide = marge par défaut',base+'marginPercent',m.marginPercent??(m.margin!=null?Math.round(m.margin*100):''),'number','min="0" max="95" step="1"')}${f('Prix de vente imposé HT (€)','salePrice')}</div>
   <p class="muted xsmall">Laissez le prix de vente vide pour appliquer la marge commerciale. Les tarifs sont HT. Les coûts de cette mission ne doivent pas être répétés dans les lignes CAPEX ou OPEX.</p>
   <div class="toolbar">${action('Enregistrer comme modèle',`saveMissionTemplate:${i}`,'sm secondary')}${action('Supprimer la mission',`deleteMission:${i}`,'sm danger')}</div></details>`;
 });
 return `<p class="lead">Budgétez séparément les prestations et les dépenses de déplacement, pour chaque phase du projet. Les coûts sont calculés sans être assimilés à des achats matériels.</p>
 ${card('Mode de préparation',`<div class="formGrid">${choice('Mode de calcul','deployment.mode',d.mode||'detailed',[['detailed','Missions détaillées'],['flat','Enveloppe simple']])}${field('Marge par défaut (%)','deployment.marginPercent',Math.round((d.margin??p.capex.margin??.3)*100),'number','min="0" max="95"')}</div>`)}
 ${d.mode==='flat'?card('Enveloppe forfaitaire',`<div class="formGrid">${field('Coût prévisionnel HT (€)','deployment.flatCost',d.flatCost??0,'number','min="0" step="0.01"')}${field('Prix de vente HT (€) · vide = marge automatique','deployment.flatSale',d.flatSale??'','number','min="0" step="0.01"')}${choice('Période','deployment.flatPhase',d.flatPhase||'before',phaseOpts)}${field('Payeur','deployment.flatOwner',d.flatOwner||'Backlight')}</div>`):
 card('Missions · installation, formation, logistique, maintenance et démontage',`<div class="toolbar">${action('＋ Mission vierge','addMission','secondary')}${choice('Ajouter depuis les modèles','deployment.templateSelect',d.templateSelect||'', [['','Choisir un modèle…'],...templates.map(x=>[x.id,x.name])])}${action('＋ Utiliser ce modèle','addFromTemplate','sm secondary')}${action('⚙ Gérer les modèles ('+templates.length+')','templateManagerToggle','sm primary')}</div>${missionManagerOpen?missionTemplateManager():''}${rows.join('')||'<p class="muted">Aucune mission. Utilisez un modèle ou ajoutez votre première mission.</p>'}`)}
 <div class="grid">${kpi('Coût total des missions HT',eur(r.total))}${kpi('Avant ouverture',eur(r.byPhase.before))}${kpi('Pendant exploitation',eur(r.byPhase.during))}${kpi('Après exploitation',eur(r.byPhase.after))}</div>
 <div class="grid">${kpi('Devis prestations HT',eur(r.sale))}${kpi('Marge prévisionnelle HT',eur(r.marginAmount))}</div>
 ${card('Ventilation et exports',table(['Mission / forfait','Phase','Payeur','Coût HT','Vente HT'],r.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(({before:'Avant',during:'Pendant',after:'Après'})[x.phase])}</td><td>${esc(x.owner||'')}</td><td>${eur(x.cost)}</td><td>${eur(x.sale)}</td></tr>`))+`<div class="toolbar">${action('Exporter missions CSV','exportMissions','sm secondary')}${action('Imprimer devis prestations client','printMissions','sm secondary')}</div><p class="muted xsmall">Les missions « Pendant exploitation » figurent dans le résultat opérationnel ; les autres dans le résultat après investissements et dépenses de déploiement, sans double comptage.</p>`)}
 `;
}
