function finance(){const p=active(),f=p.finance,r=results.finance,t=results.traffic;return `${card('Billetterie et TVA',`<div class="formGrid">${field('TVA principale (%)','settings.vatPercent',num(p.settings.vat,.2)*100,'number','min="0"')}${choice('Frais de billetterie','finance.feeMode',f.feeMode||'none',[['none','Aucun'],['included','Inclus / supportés']])}${field('Frais fixes / billet (€)','finance.feeFixed',f.feeFixed||0,'number','step="0.01" min="0"')}${field('Frais proportionnels au CA HT (%)','finance.feeRatePercent',num(f.feeRate)*100,'number','step=".1" min="0"')}</div>`)}${card('Coûts variables',`<div class="formGrid">${field('Coût par visiteur (€)','finance.variablePerVisitor',f.variablePerVisitor??0,'number','min="0" step="0.01"')}${field('Coût par session jouée (€)','finance.variablePerSession',f.variablePerSession??0,'number','min="0" step="0.01"')}${field('Coût en % du CA HT','finance.variableRatePercent',num(f.variableRate)*100,'number','min="0" step="0.1"')}</div>`)}${card('Recettes annexes',`${table(['Libellé','Montant HT (€)','Fréquence',''],(f.ancillary||[]).map((x,i)=>`<tr><td><input data-bind="finance.ancillary.${i}.name" value="${esc(x.name)}"></td><td><input type="number" data-bind="finance.ancillary.${i}.amount" value="${esc(x.amount)}"></td><td><select data-bind="finance.ancillary.${i}.frequency"><option value="once" ${x.frequency==='once'?'selected':''}>Une fois</option><option value="monthly" ${x.frequency==='monthly'?'selected':''}>Mensuel</option></select></td><td>${action('×','deleteAncillary:'+i,'sm danger')}</td></tr>`))}<div class="toolbar borderTop">${action('＋ Ajouter recette annexe','addAncillary','sm secondary')}</div>`)}<div class="grid">${kpi('Billetterie HT',eur(r.ticketHT))}${kpi('Recettes annexes HT',eur(r.ancillary))}${kpi('Dépenses prévues',eur(r.expenses))}${kpi('Résultat prévisionnel',eur(r.profit))}</div>${card('Rentabilité et équilibre',table(['Indicateur','Valeur'],[['CA TTC billetterie',eur(t.gross)],['CA HT billetterie',eur(r.ticketHT)],['OPEX fixes',eur(r.fixed)],['Personnel',eur(results.staff.cost)],['Dépenses variables',eur(r.variable)],['Missions pendant exploitation',eur(r.deploymentExpense)],['Missions avant / après exploitation',eur(r.deploymentOther)],['Frais billetterie',eur(r.fee)],['Résultat opérationnel (avant CAPEX)',eur(r.profit)],['Investissement initial (connu)',eur(results.capex.cost)],['Résultat après CAPEX + déploiement (non comptable)',eur(r.withCapex)],['Seuil fréquentation',r.breakeven==null?'Non calculable':fmt(r.breakeven)+' visiteurs']].map(v=>`<tr><td>${v[0]}</td><td><strong>${v[1]}</strong></td></tr>`)))}<div class="notice warn">Calcul financier alpha : contrats multipartenaires, billets couplés et trésorerie contractuelle détaillée sont décrits dans le cahier des charges mais ne sont pas encore calculés ici. Ne pas utiliser le résultat comme document comptable.</div>`}
function shareDraftStatus(){
 const inputs=[...document.querySelectorAll('[data-bind^="tempShare."]')];
 const total=inputs.reduce((sum,x)=>sum+num(x.value),0);
 const delta=Math.round((100-total)*100)/100;
 const ok=Math.abs(delta)<=.01;
 const label=ok?'✓ Répartition équilibrée : 100 %':delta>0?`⚠ ${fmt(delta,2)} % restent à attribuer`:`⚠ ${fmt(-delta,2)} % attribués en trop`;
 return {total,ok,label};
}
function refreshShareAlert(){const box=document.querySelector('#expenseShareAlert');if(!box)return;const value=shareDraftStatus();box.className='notice '+(value.ok?'good':'warn');box.textContent=value.label+' · total '+fmt(value.total,2)+' %';}
function partnerCharts(settlement){
 const partners=settlement.partners;
 const max=Math.max(1,...partners.flatMap(x=>[x.receipts+x.transfersIn,x.expenses+x.transfersOut]));
 return '<div class="partner-chart">'+partners.map(x=>{
  const income=x.receipts+x.transfersIn,out=x.expenses+x.transfersOut;
  return `<div class="partner-chart-row"><strong>${esc(x.name)}</strong><div><div class="flow-bar in" style="width:${Math.max(0,income/max*100)}%"></div><small>Entrées ${eur(income)}</small><div class="flow-bar out" style="width:${Math.max(0,out/max*100)}%"></div><small>Sorties ${eur(out)}</small></div></div>`;
 }).join('')+'</div><p class="muted xsmall">Entrées et sorties agrégées sur toute la période. Pas de calendrier contractuel mensuel dans cette version.</p>';
}
function partnerFlow(settlement){
 return `<div class="flow-diagram"><p><strong>Flux entrants</strong> → ${esc(active().finance.partnership?.collector||'Backlight')} : ${eur(settlement.revenue)} HT</p>`+
 (settlement.records.length?settlement.records.map(r=>`<div class="flow-line"><strong>${esc(r.payer)}</strong><span>→ ${eur(r.amount)} →</span><strong>${esc(r.beneficiary)}</strong><small>${esc(r.name)} · ${esc(r.base)}</small></div>`).join(''):'<p class="muted">Aucun transfert contractuel actif.</p>')+
 `<p class="muted xsmall">Les transferts sont internes au projet et ne s'ajoutent pas au CA consolidé.</p></div>`;
}
function cashflowCurve(rows){
 if(!rows?.length)return '<p class="muted">Aucune donnée de trésorerie mensuelle disponible.</p>';
 const values=rows.map(r=>num(r.balance)),lowest=Math.min(0,...values),highest=Math.max(0,...values),span=highest-lowest||1;
 const points=values.map((v,i)=>`${30+(i/(Math.max(1,values.length-1)))*640},${165-135*(v-lowest)/span}`).join(' ');
 const nodes=values.map((v,i)=>`<circle cx="${30+(i/Math.max(1,values.length-1))*640}" cy="${165-135*(v-lowest)/span}" r="4"><title>${esc(rows[i].month)} : ${eur(v)}</title></circle>`).join('');
 return `<div class="tablewrap"><svg viewBox="0 0 710 205" role="img" aria-label="Évolution de la trésorerie consolidée mensuelle" class="flow-curve"><line x1="30" y1="165" x2="680" y2="165" stroke="#d5dfea"/><polyline points="${points}" fill="none" stroke="#4b6cdb" stroke-width="3"/>${nodes}</svg></div><p class="muted xsmall">Courbe de trésorerie <strong>consolidée</strong> : elle ne représente pas des échéances contractuelles par partenaire (non disponibles dans cette version).</p>`;
}
function contractReport(settlement){const cfg=active().finance.partnership||{};
 const contractRows=(cfg.contracts||[]).map(c=>`<tr><td>${esc(c.name||'Sans nom')}</td><td>${esc(c.type||'')}</td><td>${esc(c.beneficiary||'')}</td><td>${esc(c.base||'ticketHT')}</td><td>${eur(num(c.amount))}</td><td>${fmt(num(c.percent),2)} %</td><td>${eur(num(c.perVisitor))}</td><td>${c.enabled===false?'Non':'Oui'}</td></tr>`).join('');
 const summaryRows=settlement.partners.map(x=>`<tr><td>${esc(x.name)}</td><td>${eur(x.receipts)}</td><td>${eur(x.transfersIn)}</td><td>${eur(x.expenses)}</td><td>${eur(x.transfersOut)}</td><td>${eur(x.balance)}</td></tr>`).join('');
 return `<h2>Contrats enregistrés</h2>${table(['Contrat','Type','Bénéficiaire','Assiette','Montant / MG','RS','Par visiteur','Actif'],contractRows)}<h2>Soldes prévisionnels HT</h2>${table(['Partenaire','Recettes','Reçoit','Dépenses','Reverse','Solde'],summaryRows)}<h2>Direction des flux</h2>${partnerFlow(settlement)}<p>${esc(settlement.disclaimer)}</p>`;
}
function revenueCircuitPanel(){
 const cfg=active().finance.partnership||{},routes=cfg.revenueRoutes||[];
 const computed=computeRevenueRoutes(routes,results), names=[...new Set(['Backlight',...(cfg.partners||[]).map(x=>x.name).filter(Boolean)])];
 const personOptions=names.map(x=>[x,x]);
 let html=`<div class="circuit-top"><div><h3>Circuits de recettes</h3><p class="muted">Définissez d'abord qui encaisse, puis comment chaque recette est distribuée. Les pourcentages sont modifiables directement.</p></div><div class="toolbar">${action('＋ Entité','addPartner','sm secondary')}${action('＋ Circuit de recette','routeAdd','primary sm')}</div></div>`;
 if(!routes.length)html+=`<div class="notice">Aucun circuit créé. Ajoutez une source de recettes pour commencer. Les contrats historiques restent inchangés tant que vous n'activez pas de circuit.</div>`;
 routes.forEach((route,i)=>{
  const c=computed.routes[i],bind='finance.partnership.revenueRoutes.'+i+'.';
  html+=`<section class="circuit-card"><div class="circuit-head"><strong>${esc(route.name||'Nouvelle recette')}</strong><span class="badge ${c.valid?'good':'warn'}">${c.enabled?(c.valid?'100 % attribués':fmt(c.total,2)+' % attribués'):'Désactivé'}</span>${action('Dupliquer','routeDuplicate:'+i,'sm secondary')}${action('Supprimer','routeRemove:'+i,'sm danger')}</div>`;
  html+=`<div class="formGrid">${field('Nom du circuit',bind+'name',route.name||'')}${choice('Recette de départ',bind+'source',route.source||'ticketHT',Object.entries(SOURCE_LABELS).map(([k,v])=>[k,v]))}${choice('Entité collectrice',bind+'collector',route.collector||cfg.collector||'Backlight',personOptions)}</div>`;
  html+=`<div class="circuit-flow"><div class="circuit-node"><small>RECETTE</small><b>${esc(SOURCE_LABELS[c.source]||c.source)}</b><strong>${eur(c.base)}</strong></div><div class="circuit-arrow">→</div><div class="circuit-node collector"><small>COLLECTEUR</small><b>${esc(route.collector||'Backlight')}</b><small>Répartit 100 % de l'assiette</small></div><div class="circuit-arrow">→</div><div class="circuit-targets">`;
  c.allocations.forEach((a,j)=>{const b=bind+'allocations.'+j+'.';html+=`<div class="circuit-target"><div class="formGrid">${choice('Bénéficiaire',b+'partner',a.partner,personOptions)}${field('Part (%)',b+'percent',a.percent,'number','min="0" max="100" step="0.01"')}</div><b>${eur(a.amount)}</b><small>${a.partner===(route.collector||'Backlight')?'Conservé par le collecteur':'À verser au bénéficiaire'}</small>${action('×','routeRemoveSplit:'+i+':'+j,'sm danger')}</div>`});
  html+=`</div></div><div class="toolbar">${action('＋ Ajouter un bénéficiaire','routeAddSplit:'+i,'sm secondary')}${check('Circuit actif',bind+'enabled',route.enabled!==false)}</div>`;
  c.errors.forEach(err=>html+=`<div class="notice warn">⚠ ${esc(err)}</div>`);
  if(c.source==='ticketTTC')html+=`<div class="notice warn">Assiette TTC : attention, la TVA ne constitue pas une recette HT distribuable.</div>`;
  html+=`<div class="circuit-footer">Total réparti : <strong>${fmt(c.total,2)} %</strong> · ${eur(c.base)} · ${c.valid?'✓ Équilibré':'⚠ Circuit non validé'}</div></section>`;
 });
 html+=`<div class="toolbar">${action('Importer un exemple 50 / 30 / 20','routeExample','sm secondary')}${action('Exporter les circuits CSV','routeExport','sm secondary')}${action('Imprimer la base économique','routePrint','sm secondary')}</div>`;
 html+=`<p class="muted xsmall">Simulation économique, pas encore un échéancier de règlements. Les anciens contrats restent enregistrés mais ne sont pas cumulés avec les circuits actifs. Les circuits sur la billetterie HT, nette et TTC sont mutuellement exclusifs pour éviter les doubles répartitions.</p>`;
 return card('Constructeur visuel — Recettes → Collecteur → Bénéficiaires',html);
}
